import { useMutation } from '@tanstack/react-query';
import { exchangeResponseDTO, RemitRequestDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useRemitDC1TrnscExecuteMutation = (
  options?: MutationOptions<RemitRequestDTO, CBDCAxiosError, exchangeResponseDTO>,
) => {
  const mutation = useMutation<exchangeResponseDTO, CBDCAxiosError, RemitRequestDTO>({
    ...options,
    mutationFn: (data: RemitRequestDTO) => exchangeApi.remitDC1Execute(data),
  });

  return {
    ...mutation,
  };
};
